contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 maxMultiplier, uint256 minMultiplier, uint256 rateParam, address vault, address asset) public {
        // Only make the rule meaningful by giving the storage a non-trivial setup first.
        // The access check on setLimits/setSlopes is satisfied if the initialization call
        // the checker performed earlier installed an access control contract; we still
        // measure the rule over the rate() return value, not the setter calls.
        uint256 before = c.rate(vault, asset); if (__ESBMC_reverted()) return;
        uint256 afterVal = c.rate(vault, asset); if (__ESBMC_reverted()) return;

        assert(before == 0 && afterVal == 0);
    }

    receive() external payable {}
}

